$(document).ready(function() {
    $('#btn-autenticidade').click(function() {
        var hash = $('#hash').val();
        $('a#download-box img').fadeOut('fast');
        if (hash != '') {
            $.ajax({
                'url': BASE_URL + '/portal/edicoes/consulta_autenticidade/' + hash,
                'success': function(data) {
                    if (data.data.error != true) {
                        carregarImagemAuternticidade(data.data.Edicao.id);
                    }
                    $('#infos-edicao').html(data.data.msg);
                }
            });
        } else {
          $('#infos-edicao').html('');
        }
    });

      $('#btn-autenticidade-materia').click(function() {
        let hash = $('#hashMateria').val();
        if (hash != '') {
            $.post({
                url: BASE_URL + '/portal/edicoes/consulta_aut_materia/',
                data: {protocolo: hash},
                success: function(data) {
                    $('#infos-edicao-materia').html(data.data.msg + '. Clique <a href="'+ data.data.url+'" target="_blank">aqui</a> para visualizar');
                },
                error: function(e) {
                    alert(e.responseJSON.message);
                }
            });
        } else {
          $('#infos-edicao-materia').html('');
        }
    });
});

function carregarImagemAuternticidade(edicao_id) {
    if (edicao_id > 0) {
        var url = BASE_URL + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/apifront/portal/edicoes/imagem_diario/' + edicao_id + '/1/imagem';
        $('a#download-box img').show();
        var imagem = $('<div class="processing"></div>');
        $("#imagem-diario").parent().append(imagem);
        var im = new Image();
        im.onload = function() {
            $("#imagem-diario").fadeOut('fast');
            $("#imagem-diario").attr('src', url).fadeIn('fast');
            $("#imagem-diario").parent().find(".processing").fadeOut('slow', function() {
                $(this).remove();
            });
        }
        im.src = url;
        $('a#download-box').attr('href', BASE_URL + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/portal/edicoes/download/' + edicao_id);
    }
}

