}

/*================================ MINIATURA COM FADE ====================================*/

.diario-thumb-container {
    position: relative;
    width: 100%;
}

.diario-thumb-image {
    opacity: 1;
    display: block;
    width: 100%;
    height: auto;
    transition: .5s ease;
    backface-visibility: hidden;
}

.diario-thumb-middle {
    transition: .5s ease;
    opacity: 0;
    position: absolute;
    top: 15%;
    left: 12%;
    text-align: center;
}

.diario-thumb-container:hover .diario-thumb-image {
    opacity: 0.1;
}

.diario-thumb-container:hover .diario-thumb-middle {
    opacity: 1;
}

.diario-thumb-left-button {
    width: 100%;
    padding: 10px 10px;
    display: block;
    font-size: 14pt;
    margin-bottom: 10px;
}

.diario-thumb-right-button {
    width: 100%;
    padding: 10px 10px;
    display: block;
    font-size: 14pt;
}

.diario-thumb-texto-visualizao {
    color: #d22323;
    font-size: 14pt;
    width: 100%;
}

